with filtered as (select *, date_trunc('month', start_date) as start_date_period, round(monthly_fee * 0.9, 2) as monthly_fee_scaled from subscriptions where end_date >= to_date('2023-10-20') and end_date >= '2024-01-01') select * from (select customer_id, status, monthly_fee from filtered) src pivot (avg(monthly_fee) as value_sum, count(1) as item_count for status in ('CANCELLED', 'EXPIRED'));
